ExtremeValueTheory.IsRegularlyVarying.tendstoUniformlyOn_of_isCompact {f : ℝ → ℝ} {ρ : ℝ}
  (hf : ExtremeValueTheory.IsRegularlyVarying f ρ) {a : ℝ}
  (hmono : MonotoneOn f (Set.Ici a) ∨ AntitoneOn f (Set.Ici a)) {K : Set ℝ} (hK : IsCompact K)
  (hK0 : K ⊆ Set.Ioi 0) :
  TendstoUniformlyOn (fun x c => f (c * x) / f x) (fun c => c ^ ρ) Filter.atTop K

